-- Conferência do script 08 — SOMENTE LEITURA (não cria, não altera, não apaga nada) — 28 itens
with f as (select p.oid, p.proname, p.prosecdef, p.proconfig from pg_proc p where p.pronamespace = 'api'::regnamespace)
select 1 as item, 'Scripts registrados' as verificacao, (select string_agg(versao, ',' order by versao) from app.versoes_esquema) as resultado, '00,01,02,03,04,05,06,06.1,07,08' as esperado
union all select 2, 'Schema api: portal usa, anônimo não', (has_schema_privilege('authenticated', 'api', 'usage') and not has_schema_privilege('anon', 'api', 'usage'))::text, 'true'
union all select 3, 'Operações do schema api', (select string_agg(proname, ',' order by proname) from f), 'afastar_eliminatorio,cancelar_monitoria,confirmar_zeramento,devolver_monitoria,fila_validacao,publicar_regua,reprovar_monitoria,salvar_monitoria,validar_monitoria'
union all select 4, 'Operações que o anônimo executa', (select count(*)::text from f where has_function_privilege('anon', f.oid, 'execute')), '0'
union all select 5, 'Operações que o portal logado executa', (select count(*)::text from f where has_function_privilege('authenticated', f.oid, 'execute')), '9'
union all select 6, 'Fila de validação roda com as permissões de quem chama (RLS vale)', (select (not prosecdef)::text from f where proname = 'fila_validacao'), 'true'
union all select 7, 'Operações com search_path fixo', (select count(*)::text from f where array_to_string(proconfig, ',') like '%search_path=%'), '9'
union all select 8, 'Funções no schema app / com search_path fixo', (select count(*)::text || ' / ' || count(*) filter (where array_to_string(proconfig, ',') like '%search_path=%')::text from pg_proc where pronamespace = 'app'::regnamespace), '33 / 33'
union all select 9, 'Funções do app que o portal executa — inalteradas', (select string_agg(proname, ',' order by proname) from pg_proc p where p.pronamespace = 'app'::regnamespace and has_function_privilege('authenticated', p.oid, 'execute')), 'equipe_do_gestor,meu_perfil_id,meus_perfis,sou_admin,tem_perfil,usuario_ativo,usuario_liberado'
union all select 10, 'Colunas novas em monitorias', (select count(*)::text from information_schema.columns where table_schema = 'public' and table_name = 'monitorias' and column_name in ('nota_calculada', 'nota_historica', 'origem', 'enviado_em', 'motivo_reprovacao', 'eliminatorio_afastado_por', 'eliminatorio_afastado_em', 'eliminatorio_afastado_motivo', 'cancelado_por', 'cancelado_em', 'cancelado_motivo', 'enviada_na_origem')), '12'
union all select 11, 'Respostas com remoção lógica (coluna ativo)', (select count(*)::text from information_schema.columns where table_schema = 'public' and table_name = 'monitoria_respostas' and column_name = 'ativo'), '1'
union all select 12, 'Regras de origem (portal/migracao) e de enviada_na_origem (só migradas)', (select count(*)::text from pg_constraint where conrelid = 'public.monitorias'::regclass and conname in ('monitorias_origem_valida', 'monitorias_enviada_na_origem')), '2'
union all select 13, 'Vigência de versão nova da régua não retroativa (gatilho)', (select count(*)::text from pg_trigger where tgrelid = 'public.regua_versoes'::regclass and tgname = 'regua_versoes_a_vigencia'), '1'
union all select 14, 'Portal continua sem gravação direta em monitorias, respostas e evidências', (select coalesce(bool_or(has_table_privilege('authenticated', c.oid, 'insert') or has_table_privilege('authenticated', c.oid, 'update')), false)::text from pg_class c where c.oid in ('public.monitorias'::regclass, 'public.monitoria_respostas'::regclass, 'public.monitoria_evidencias'::regclass)), 'false'
union all select 15, 'Funções no schema public (nada exposto fora do api)', (select count(*)::text from pg_proc where pronamespace = 'public'::regnamespace), '0'
union all select 16, 'Regras RLS (as 40 do 07, menos a inclusão direta na régua)', (select count(*)::text from pg_policies where schemaname = 'public'), '39'
union all select 17, 'Monitorias gravadas (o 08 não grava dados)', (select count(*)::text from public.monitorias), '0'
union all select 18, 'Quebras na cadeia da auditoria', (select count(*)::text from (select a.hash <> app.auditoria_hash(a) or a.hash_anterior is distinct from lag(a.hash) over (order by a.seq) quebra from public.auditoria a) x where quebra), '0'
union all select 19, 'ÂNCORA da auditoria — anotar fora do banco', coalesce((select seq::text || ' | ' || hash from public.auditoria order by seq desc limit 1), 'trilha vazia'), 'anotar'
union all select 20, 'Versões da régua publicadas (informativo; regua-1 e regua-2.0 vêm no 09)', coalesce((select string_agg(id || ' desde ' || vigente_desde, ', ' order by vigente_desde) from public.regua_versoes), 'nenhuma'), 'qualquer'
union all select 21, 'Funções de app e api que o anônimo executa', (select count(*)::text from pg_proc p where p.pronamespace in ('app'::regnamespace, 'api'::regnamespace) and has_function_privilege('anon', p.oid, 'execute')), '0'
union all select 22, 'Funções de app e api abertas a PUBLIC (todos os papéis)', (select count(*)::text from pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where p.pronamespace in ('app'::regnamespace, 'api'::regnamespace) and a.grantee = 0), '0'
union all select 23, 'Sequências de public e app utilizáveis pelo portal ou anônimo', (select count(*)::text from pg_class c where c.relkind = 'S' and c.relnamespace in ('public'::regnamespace, 'app'::regnamespace) and (has_sequence_privilege('authenticated', c.oid, 'usage') or has_sequence_privilege('authenticated', c.oid, 'update') or has_sequence_privilege('anon', c.oid, 'usage') or has_sequence_privilege('anon', c.oid, 'update'))), '0'
union all select 24, 'Portal ou anônimo podem CRIAR objetos em app ou api', (has_schema_privilege('authenticated', 'app', 'create') or has_schema_privilege('authenticated', 'api', 'create') or has_schema_privilege('anon', 'app', 'create') or has_schema_privilege('anon', 'api', 'create') or has_schema_privilege('anon', 'app', 'usage'))::text, 'false'
union all select 25, 'Papéis herdados por anon/authenticated e superpoderes', coalesce((select string_agg(b.rolname || '∈' || r.rolname, ',') from pg_roles b join pg_roles r on pg_has_role(b.oid, r.oid, 'member') and b.oid <> r.oid where b.rolname in ('anon', 'authenticated')), 'nenhum') || ' / ' || (select bool_or(rolsuper or rolbypassrls or rolcreaterole or rolcreatedb)::text from pg_roles where rolname in ('anon', 'authenticated')), 'nenhum / false'
union all select 26, 'Régua publicada: gatilhos de proteção / permissões do portal', (select count(*)::text from pg_trigger where tgrelid = 'public.regua_versoes'::regclass and tgname in ('regua_versoes_bloqueio_alteracao', 'regua_versoes_sem_exclusao', 'regua_versoes_sem_truncate', 'regua_versoes_a_vigencia')) || ' / ' || concat_ws(',', case when has_table_privilege('authenticated', 'public.regua_versoes', 'select') then 'SELECT' end, case when has_table_privilege('authenticated', 'public.regua_versoes', 'insert') then 'INSERT' end, case when has_table_privilege('authenticated', 'public.regua_versoes', 'update') then 'UPDATE' end, case when has_table_privilege('authenticated', 'public.regua_versoes', 'delete') then 'DELETE' end, case when has_table_privilege('authenticated', 'public.regua_versoes', 'truncate') then 'TRUNCATE' end), '4 / SELECT'
union all select 27, 'Permissões automáticas do projeto (informativo: o 08 neutraliza em app e api)', coalesce((select string_agg(coalesce(n.nspname, '(global)') || ':' || case d.defaclobjtype when 'f' then 'funções' when 'r' then 'tabelas' when 'S' then 'sequências' when 'n' then 'schemas' else d.defaclobjtype::text end || '→' || array_to_string(array(select distinct pg_get_userbyid(x.grantee) from aclexplode(d.defaclacl) x where x.grantee <> 0 and pg_get_userbyid(x.grantee) in ('anon', 'authenticated')), '+'), '; ' order by 1) from pg_default_acl d left join pg_namespace n on n.oid = d.defaclnamespace where exists (select 1 from aclexplode(d.defaclacl) x where pg_get_userbyid(x.grantee) in ('anon', 'authenticated'))), 'nenhuma'), 'qualquer'
union all select 28, 'Publicação da régua só pela função: políticas de inclusão em regua_versoes / publicar_regua é SECURITY DEFINER, search_path vazio, dono da tabela', (select count(*)::text from pg_policies where schemaname = 'public' and tablename = 'regua_versoes' and cmd in ('INSERT', 'ALL')) || ' / ' || (select (p.prosecdef and p.proconfig @> array['search_path=""'] and p.proowner = (select relowner from pg_class where oid = 'public.regua_versoes'::regclass))::text from pg_proc p where p.oid = 'api.publicar_regua(text, text, date, text)'::regprocedure), '0 / true'
order by item;
